template:
prometheus.exporter.cloudwatch "${1:default}" {
  discovery {
    regions = "${2}"
    type = "${3}"
    metric {
      $0
    }
  }
  static {
    dimensions = "${2}"
    namespace = "${3}"
    regions = "${4}"
    metric {
      $0
    }
  }
  custom_namespace {
    namespace = "${2}"
    regions = "${3}"
    metric {
      $0
    }
  }
  decoupled_scraping {
  }

  // Exported fields:
  // - targets (list(map(string))): The targets that can be used to collect exporter metrics.
}
